#include "window.h"
#include "version.h"
#include "caption.h"
int selfTest(Window&,QString,bool);
int main(int argc,char** argv){QApplication app(argc,argv);QCoreApplication::setApplicationVersion(PSD_APP_VERSION);app.installEventFilter(new CaptionTheme(&app));QApplication::setStyle("Fusion");QApplication::setFont(QFont("Segoe UI",9));auto args=app.arguments();bool testing=args.contains("--self-test")||args.contains("--benchmark");if(testing){QSettings::setDefaultFormat(QSettings::IniFormat);QSettings::setPath(QSettings::IniFormat,QSettings::UserScope,QCoreApplication::applicationDirPath()+"/test-settings");}QSettings preferences("Miroir","PSD命名修改原生版");setUiLanguage(testing?"zh":preferences.value("ui-language","zh").toString());Window window;window.show();if(testing){int at=args.indexOf(args.contains("--benchmark")?"--benchmark":"--self-test");QTimer::singleShot(150,&window,[&]{int status=selfTest(window,args.value(at+1),args.contains("--benchmark"));app.exit(status);});}else if(args.size()>1){QTimer::singleShot(100,&window,[&]{window.load(args[1]);});}return app.exec();}
